      model: "Assets: $8,200 + $1,450 + $180 + $240 = $10,070. Liabilities: $90 + $300 = $390. Accumulated fund = $10,070 − $390 = $9,680.",
      points: ["Subscriptions in arrears and inventory treated as assets (1)", "Total assets $10,070 (1)", "Subscriptions in advance and rent owing treated as liabilities, $390 (1)", "Accumulated fund $9,680 (1)"],
